=<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Formulario Syllabus</title>
<script src="https://cdn.tailwindcss.com"></script>

<style>
.spinner {
  border: 2px solid transparent;
  border-top-color: white;
  border-radius: 9999px;
  width: 1rem;
  height: 1rem;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Estilos para mensajes de error */
.error-message {
  color: #dc2626;
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

.input-error {
  border-color: #dc2626 !important;
  background-color: #fef2f2 !important;
}

/* Estilo para tooltip de validación */
.validation-hint {
  font-size: 0.75rem;
  color: #6b7280;
  margin-top: 0.25rem;
}
</style>
</head>

<body class="bg-gray-100 min-h-screen flex items-center justify-center p-6">

<form
  id="syllabusForm"
  method="POST"
  action="https://hpa.lugnia.com/webhook/pertinencia"
  class="w-full max-w-xl bg-white p-6 rounded-xl shadow space-y-4"
>

<h1 class="text-xl font-bold text-gray-800">
  Recomendación de recursos con IA
</h1>

<div>
  <label class="block text-sm font-medium mb-1">Programa académico</label>
  <input type="text" name="programa_academico" placeholder="Ej: Ingeniería de Sistemas, Tecnología en Desarrollo de Software" class="w-full border rounded px-3 py-2" required>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Nombre de la materia</label>
  <input type="text" name="nombre_materia" placeholder="Ej: Fundamentos de Programación" class="w-full border rounded px-3 py-2" required>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Descripción general</label>
  <textarea name="descripcion_general" placeholder="Descripción de la asignatura" class="w-full border rounded px-3 py-2" rows="3" required></textarea>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Competencias / Resultados de aprendizaje <span class="text-gray-500 text-xs">(opcional)</span></label>
  <textarea name="competencias" placeholder="Competencias y/o resultados de aprendizaje de la asignatura" class="w-full border rounded px-3 py-2" rows="3"></textarea>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Temario</label>
  <textarea name="temario" placeholder="Temas incluidos en la asignatura" class="w-full border rounded px-3 py-2" rows="4" required></textarea>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Palabras clave del syllabus</label>
  <input type="text" id="palabrasClave" name="palabras_clave_syllabus" placeholder="Ej: programación, algoritmos, estructuras de datos, POO, Java, variables, funciones, arrays" class="w-full border rounded px-3 py-2" required>
  <div class="validation-hint">Mínimo 8 palabras separadas por comas. Ej: palabra1, palabra2, palabra3...</div>
  <div id="palabrasClaveError" class="error-message"></div>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Términos excluyentes <span class="text-gray-500 text-xs">(opcional)</span></label>
  <input type="text" id="terminosExcluyentes" name="terminos_excluyentes" placeholder="Ej: conceptos básicos, introducción, fundamentos" class="w-full border rounded px-3 py-2">
  <div class="validation-hint">Separar por comas si se incluyen varios términos</div>
  <div id="terminosExcluyentesError" class="error-message"></div>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Email docente</label>
  <input type="email" id="emailDocente" name="email_docente" placeholder="ejemplo@universidad.edu.co" class="w-full border rounded px-3 py-2" required>
  <div id="emailDocenteError" class="error-message"></div>
</div>

<div>
  <label class="block text-sm font-medium mb-1">Llave del agente</label>
  <input type="text" id="idKey" name="id_key" placeholder="abc-123" class="w-full border rounded px-3 py-2" required>
  <div id="idKeyError" class="error-message"></div>
</div>

<button
  id="submitBtn"
  type="submit"
  class="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-lg flex items-center justify-center gap-2"
>
  <span id="btnText">Analizar syllabus</span>
  <span id="btnLoader" class="hidden items-center gap-2">
    <span class="spinner"></span>
    Analizando...
  </span>
</button>

</form>

<script>
const form = document.getElementById("syllabusForm");
const button = document.getElementById("submitBtn");
const text = document.getElementById("btnText");
const loader = document.getElementById("btnLoader");
const palabrasClaveInput = document.getElementById("palabrasClave");
const terminosExcluyentesInput = document.getElementById("terminosExcluyentes");
const emailDocenteInput = document.getElementById("emailDocente");

// Función para validar palabras clave (mínimo 8, separadas por comas)
function validarPalabrasClave(valor) {
  if (!valor || valor.trim() === "") {
    return { valido: false, mensaje: "Las palabras clave son obligatorias" };
  }

  // Separar por comas y limpiar espacios
  const palabras = valor.split(",").map(p => p.trim()).filter(p => p !== "");

  if (palabras.length < 8) {
    return { valido: false, mensaje: `Debe ingresar mínimo 8 palabras clave. Actualmente tiene ${palabras.length}.` };
  }

  // Verificar que no haya comas al inicio o final
  if (valor.startsWith(",") || valor.endsWith(",")) {
    return { valido: false, mensaje: "No debe comenzar o terminar con coma" };
  }

  // Verificar que no haya comas seguidas
  if (valor.includes(",,")) {
    return { valido: false, mensaje: "No debe tener comas consecutivas" };
  }

  return { valido: true, mensaje: "", palabras: palabras };
}

// Función para validar términos excluyentes (formato de comas)
function validarTerminosExcluyentes(valor) {
  if (!valor || valor.trim() === "") {
    return { valido: true, mensaje: "" }; // Es opcional
  }

  // Verificar que no haya comas al inicio o final
  if (valor.startsWith(",") || valor.endsWith(",")) {
    return { valido: false, mensaje: "Los términos excluyentes no deben comenzar o terminar con coma" };
  }

  // Verificar que no haya comas seguidas
  if (valor.includes(",,")) {
    return { valido: false, mensaje: "Los términos excluyentes no deben tener comas consecutivas" };
  }

  // Verificar que tenga al menos un término válido
  const terminos = valor.split(",").map(t => t.trim()).filter(t => t !== "");
  if (terminos.length === 0 && valor.trim() !== "") {
    return { valido: false, mensaje: "Formato inválido. Separe los términos con comas" };
  }

  return { valido: true, mensaje: "", terminos: terminos };
}

// Función para validar email
function validarEmail(email) {
  if (!email || email.trim() === "") {
    return { valido: false, mensaje: "El email del docente es obligatorio" };
  }

  // Expresión regular para validar email
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return { valido: false, mensaje: "Ingrese un email válido (ejemplo@dominio.com)" };
  }

  return { valido: true, mensaje: "" };
}

// Función para mostrar error en un campo
function mostrarError(input, mensaje, elementoError) {
  if (mensaje) {
    input.classList.add("input-error");
    elementoError.textContent = mensaje;
  } else {
    input.classList.remove("input-error");
    elementoError.textContent = "";
  }
}

// Función para validar todos los campos
function validarFormulario() {
  let esValido = true;

  // Validar palabras clave
  const palabrasClave = palabrasClaveInput.value;
  const resultadoPalabras = validarPalabrasClave(palabrasClave);
  mostrarError(palabrasClaveInput, resultadoPalabras.mensaje, document.getElementById("palabrasClaveError"));
  if (!resultadoPalabras.valido) esValido = false;

  // Validar términos excluyentes
  const terminosExcluyentes = terminosExcluyentesInput.value;
  const resultadoTerminos = validarTerminosExcluyentes(terminosExcluyentes);
  mostrarError(terminosExcluyentesInput, resultadoTerminos.mensaje, document.getElementById("terminosExcluyentesError"));
  if (!resultadoTerminos.valido) esValido = false;

  // Validar email docente
  const email = emailDocenteInput.value;
  const resultadoEmail = validarEmail(email);
  mostrarError(emailDocenteInput, resultadoEmail.mensaje, document.getElementById("emailDocenteError"));
  if (!resultadoEmail.valido) esValido = false;

  return esValido;
}

// Agregar validación en tiempo real para palabras clave
palabrasClaveInput.addEventListener("input", function() {
  const valor = this.value;
  const resultado = validarPalabrasClave(valor);
  if (!resultado.valido && valor !== "") {
    mostrarError(this, resultado.mensaje, document.getElementById("palabrasClaveError"));
  } else {
    mostrarError(this, "", document.getElementById("palabrasClaveError"));
  }
});

// Agregar validación en tiempo real para términos excluyentes
terminosExcluyentesInput.addEventListener("input", function() {
  const valor = this.value;
  const resultado = validarTerminosExcluyentes(valor);
  if (!resultado.valido && valor !== "") {
    mostrarError(this, resultado.mensaje, document.getElementById("terminosExcluyentesError"));
  } else {
    mostrarError(this, "", document.getElementById("terminosExcluyentesError"));
  }
});

// Agregar validación en tiempo real para email
emailDocenteInput.addEventListener("input", function() {
  const valor = this.value;
  const resultado = validarEmail(valor);
  if (!resultado.valido && valor !== "") {
    mostrarError(this, resultado.mensaje, document.getElementById("emailDocenteError"));
  } else {
    mostrarError(this, "", document.getElementById("emailDocenteError"));
  }
});

// Validación antes de enviar el formulario
form.addEventListener("submit", (event) => {
  // Validar el formulario
  if (!validarFormulario()) {
    event.preventDefault(); // Evitar envío si hay errores
    return;
  }

  // Bloquear botón
  button.disabled = true;
  button.classList.add("opacity-70", "cursor-not-allowed");

  // Cambiar contenido
  text.classList.add("hidden");
  loader.classList.remove("hidden");
  loader.classList.add("flex");

  // Limpiar los valores de los campos de error visual antes de enviar
  mostrarError(palabrasClaveInput, "", document.getElementById("palabrasClaveError"));
  mostrarError(terminosExcluyentesInput, "", document.getElementById("terminosExcluyentesError"));
  mostrarError(emailDocenteInput, "", document.getElementById("emailDocenteError"));
});

// También validar al intentar enviar con Enter en cualquier campo
const todosLosInputs = form.querySelectorAll("input, textarea");
todosLosInputs.forEach(input => {
  input.addEventListener("keypress", (event) => {
    if (event.key === "Enter" && input.tagName !== "TEXTAREA") {
      event.preventDefault();
      if (validarFormulario()) {
        form.dispatchEvent(new Event("submit"));
      }
    }
  });
});

// Validación adicional antes de enviar si se usa el botón con click
button.addEventListener("click", (event) => {
  if (!validarFormulario()) {
    event.preventDefault();
    // Mostrar mensaje de error general
    const primerError = document.querySelector(".input-error");
    if (primerError) {
      primerError.scrollIntoView({ behavior: "smooth", block: "center" });
      primerError.focus();
    }
  }
});
</script>

</body>
</html>
